DELETE FROM FILES
 WHERE FILE_ID = #{fileId}
   AND FILE_ATTACH_SEQ = #{fileAttachSeq}
   AND FILE_SOURCE_REF = 'BROKER_INTRO'

mapper.update:
UPDATE FILES
SET
	FILE_DIR = #{fileDir}
	, FILE_SOURCE_ID = #{fileSourceId}
	, FILE_ATTACH_SEQ = #{fileAttachSeq}
	, FILE_SOURCE_REF = #{fileSourceRef}
	, FILE_SAVEDNAME = #{fileSavedname}
	, FILE_ORIGINALNAME = #{fileOriginalname}
	, FILE_MIME = #{fileMime}
	, FILE_SIZE = #{fileSize}
	, DOC_TYPE_CD = #{docTypeCd}
	, FILE_PATH_URL = #{filePathUrl}
	, REG_DTM = #{regDtm}
WHERE FILE_ID = #{fileId}
